function countRuns(bits: number[], goal: number): number {
  let count = 0;
  for (let i = 0; i < bits.length; i++) {
    let sum = 0;
    for (let j = i; j < bits.length; j++) {
      sum += bits[j];
      if (sum === goal) count++;
      else if (sum > goal) break;
    }
  }
  return count;
}

