function countRuns(bits: number[], goal: number): number {
  const seen = new Map<number, number>([[0, 1]]);
  let prefix = 0, count = 0;
  for (const b of bits) {
    prefix += b;
    count += seen.get(prefix - goal) ?? 0;
    seen.set(prefix, (seen.get(prefix) ?? 0) + 1);
  }
  return count;
}

