function countRuns(bits: number[], goal: number): number {
  const atMost = (g: number): number => {
    if (g < 0) return 0;
    let left = 0, sum = 0, count = 0;
    for (let right = 0; right < bits.length; right++) {
      sum += bits[right];
      while (sum > g) sum -= bits[left++];
      count += right - left + 1;
    }
    return count;
  };
  return atMost(goal) - atMost(goal - 1);
}

